def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = [(r, c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((color,cells))
    return out

def l_marker(color, cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    s=set(cells)
    # The marker is a thin, one-cell L with two full straight arms.
    if len(cells) != (r1-r0+1)+(c1-c0+1)-1:
        return None
    for r in (r0,r1):
        for c in (c0,c1):
            if all((r,x) in s for x in range(c0,c1+1)) and all((y,c) in s for y in range(r0,r1+1)):
                return (r,c, (1 if r==r0 else -1), (1 if c==c0 else -1), len(cells))
    return None

def transform(grid):
    bg=grid[0][0]
    comps=components(grid)
    markers=[]
    for color,cells in comps:
        m=l_marker(color,cells)
        if m and len(cells)>=8:
            markers.append((m[4],color,cells,m))
    if not markers:
        return [row[:] for row in grid]
    _, marker_color, marker_cells, (r0,c0,vert,horiz,_) = max(markers,key=lambda x:x[0])
    # Search on the side opposite the vertical arm, and on the side indicated by the horizontal arm.
    targets=[]
    for color,cells in comps:
        if color in (bg,0,marker_color) or cells is marker_cells:
            continue
        eligible=[]
        for r,c in cells:
            if (r-r0)*vert < 0 and (c-c0)*horiz >= 0:
                eligible.append((r,c))
        if eligible:
            score=min(abs(r-r0)+abs(c-c0) for r,c in eligible)
            targets.append((score,-len(cells),color,cells))
    if not targets:
        return [row[:] for row in grid]
    _,_,_,cells=min(targets,key=lambda x:(x[0],x[1]))
    out=[row[:] for row in grid]
    for r,c in cells:
        out[r][c]=marker_color
    return out

