    cc = sum(c for r, c in points) / len(points)
    for color in set(grid[r][c] for r, c in points):
        cells = {(r, c) for r, c in points if grid[r][c] == color}
        # Diagonal two-pixel-or-longer runs; extend the more outward endpoint.
