def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(g[rr][cc] == 3 for rr in range(r-1, r+2) for cc in range(c-1, c+2) if (rr, cc) != (r, c)):
                centers.append((r, c))
    if not centers:
        return g
    # The long 2-lines are the rails; paint a perpendicular 1-line through each target.
    col_rails = [c for c in range(w) if all(g[r][c] != 0 for r in range(h))]
    row_rails = [r for r in range(h) if all(g[r][c] != 0 for c in range(w))]
    vertical_rails = len(col_rails) >= len(row_rails)
    for r, c in centers:
        if vertical_rails:
            for x in range(w):
                if g[r][x] == 0:
                    g[r][x] = 1
            for x in col_rails:
                if x == c:
                    continue
                # A crossing leaves 2 on the forward (rightward) side and is painted 1 behind it.
                center_color = 2 if len(col_rails) > 2 or x > c else 1
                for rr in range(max(0, r-1), min(h, r+2)):
                    for cc in range(max(0, x-1), min(w, x+2)):
                        if g[rr][cc] != 3:
                            g[rr][cc] = 1
                g[r][x] = center_color
        else:
            for y in range(h):
                if g[y][c] == 0:
                    g[y][c] = 1
            for y in row_rails:
                if y == r:
                    continue
                center_color = 2
                for rr in range(max(0, y-1), min(h, y+2)):
                    for cc in range(max(0, c-1), min(w, c+2)):
                        if g[rr][cc] != 3:
                            g[rr][cc] = 1
                g[y][c] = center_color
    return g

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A vertical 5-line extends the adjacent colored tile along its length.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5 or (r > 0 and grid[r - 1][c] == 5):
                r += 1
                continue
            end = r
            while end + 1 < h and grid[end + 1][c] == 5:
                end += 1
            if c + 1 < w and grid[end][c + 1] not in (0, 5):
                x = c + 1
                while x < w and grid[end][x] not in (0, 5):
                    x += 1
                width = x - c - 1
                tile = []
                y = end
                while y >= r and all(grid[y][xx] not in (0, 5) for xx in range(c + 1, x)):
                    tile.append(grid[y][c + 1:x])
                    y -= 1
                if tile:
                    for yy in range(r, end + 1):
                        values = tile[(end - yy) % len(tile)]
                        out[yy][c + 1:x] = values[:]
            r = end + 1

    # A horizontal 5-line extends a vertical colored tile from its left end.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5 or (c > 0 and grid[r][c - 1] == 5):
                c += 1
                continue
            end = c
            while end + 1 < w and grid[r][end + 1] == 5:
                end += 1
            if r + 1 < h and grid[r + 1][c] not in (0, 5):
                y = r + 1
                while y < h and grid[y][c] not in (0, 5):
                    y += 1
                tile = [grid[yy][c] for yy in range(r + 1, y)]
                for xx in range(c, end + 1):
                    for offset, value in enumerate(tile):
                        out[r + 1 + offset][xx] = value
            c = end + 1
    return out

