    shapes = {
        1: {(0, 0), (0, 1), (1, 0), (1, 1)},
        2: {(0, 1), (1, 0), (1, 1)},
        3: {(0, 0), (0, 1), (1, 1)},
        4: {(0, 0), (1, 0), (1, 1)},
    }
    placements = []
    for color, shape in shapes.items():
        for r in range(h - 1):
            for c in range(w - 1):
                cells = {(r + dr, c + dc) for dr, dc in shape}
                if cells <= foreground:
                    placements.append((color, cells))
    by_cell = {cell: [] for cell in foreground}
    for placement in placements:
        for cell in placement[1]:
            by_cell[cell].append(placement)

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for color, cells in by_cell[cell]:
            if cells <= remaining:
                rest = cover(remaining - cells)
                if rest is not None:
                    return [(color, cells)] + rest
        return None

    pieces = cover(foreground)
    result = [[0] * w for _ in range(h)]
    for color, cells in pieces:
        for r, c in cells:
            result[r][c] = color
    return result

