def transform(grid):
    h, w = len(grid), len(grid[0])
    border_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    border_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    upward = bool(border_rows and border_rows[0] == 0) or bool(border_cols and border_cols[0] == 0)
    if border_rows:
        border = border_rows[0]
        direction = -1 if upward else 1
    elif border_cols:
        border = border_cols[0]
        direction = -1 if border == 0 else 1
    else:
        return [row[:] for row in grid]

    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 2)}
    components = []
    while remaining:
        seed = remaining.pop()
        color = grid[seed[0]][seed[1]]
        cells = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                pos = (nr, nc)
                if pos in remaining and grid[nr][nc] == color:
                    remaining.remove(pos)
                    cells.add(pos)
                    stack.append(pos)
        components.append((color, cells))

    if border_rows:
        components.sort(key=lambda item: min(r for r, c in item[1]) if direction < 0 else -max(r for r, c in item[1]))
        landed = {(border, c) for c in range(w)}
        out = [[0] * w for _ in range(h)]
        out[border] = [2] * w
        for color, cells in components:
            while True:
                shifted = {(r + direction, c) for r, c in cells}
                if any(r < 0 or r >= h or (r, c) in landed for r, c in shifted):
                    break
                cells = shifted
            for r, c in cells:
                out[r][c] = color
                landed.add((r, c))
        return out

    # Vertical border: gravity is toward that side.
    direction = -1 if border == 0 else 1
    components.sort(key=lambda item: min(c for r, c in item[1]) if direction < 0 else -max(c for r, c in item[1]))
    landed = {(r, border) for r in range(h)}
