    for r in range(h):
        out[r][border] = 2
    for color, cells in components:
        while True:
            shifted = {(r, c + direction) for r, c in cells}
            if any(c < 0 or c >= w or (r, c) in landed for r, c in shifted):
                break
            cells = shifted
        for r, c in cells:
            out[r][c] = color
            landed.add((r, c))
    return out

